(x, y, t) => {
  const warp1 = (px, py) => [
    Math.sin(px*0.018+t*0.3)*18+Math.cos(py*0.022-t*0.25)*14+Math.sin((px+py)*0.01+t*0.15)*10,
    Math.cos(py*0.02-t*0.28)*18+Math.sin(px*0.016+t*0.32)*14+Math.cos((px-py)*0.012-t*0.18)*10
  ];
  const [w1x,w1y]=warp1(x,y),[w2x,w2y]=warp1(x+w1x*0.5,y+w1y*0.5);
  const sx=x+w1x+w2x*0.3,sy=y+w1y+w2y*0.3;
  const src=[
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.07,2.0,1.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.09,1.7,0.8],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.055,2.3,1.2],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.11,1.5,0.7],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.065,2.6,1.1],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.08,1.9,0.9],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+2)*50,0.13,1.3,0.6],
    [400+Math.cos(t*0.55+1)*60,200+Math.sin(t*0.75+4)*40,0.075,2.1,1.0]
  ];
  let aS=0,iS=0,diff=0;
  for(const[sX,sY,f,sp,amp]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp)*amp;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*amp;
    diff+=Math.sin(d*f*1.3-t*sp*0.8+0.7)*amp*0.5;
  }
  const n=src.length,act=aS/n,inh=iS/n,df=diff/n;
  const bg=(Math.sin(sx*0.035+sy*0.022+t*0.8)+Math.sin(sx*0.028-sy*0.038+t*1.1)+Math.sin((sx+sy)*0.11+t*2.5)*0.3+Math.sin((sx-sy)*0.09-t*2.0)*0.3+Math.sin(sx*0.06+sy*0.04-t*1.5)*0.2)/3.0;
  const cx=240,cy=120,dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.045-ang*3-t*1.5)+Math.sin(dist*0.035+ang*4-t*1.2)+Math.sin(dist*0.06-ang*2+t*0.8)*0.5)*0.35;
  const detail=Math.sin(sx*0.12)*Math.sin(sy*0.12)*Math.cos((sx+sy)*0.08+t*0.5)*0.3;
  const raw=act-inh*0.7+bg*0.3+spiral+df*0.4+detail;
  const reaction=Math.tanh(raw*2.0);
  const reaction2=Math.tanh((act*0.5+df*0.8-spiral*0.3+bg*0.2)*1.8);
  const blend=reaction*0.7+reaction2*0.3;
  const dx=blend-Math.tanh((raw+0.5)*2.0);
  const edge=Math.min(1.0,Math.abs(dx)*8.0);
  const v=blend*0.5+0.5;
  const pal=[[5,10,42],[12,45,85],[18,95,120],[25,150,130],[120,185,100],[210,195,60],[225,145,55],[200,85,60],[150,45,70],[85,20,55],[40,12,45],[5,10,42]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const cf=f*f*(3-2*f);
  const r=pal[i][0]+(pal[i+1][0]-pal[i][0])*cf;
  const g=pal[i][1]+(pal[i+1][1]-pal[i][1])*cf;
  const b=pal[i][2]+(pal[i+1][2]-pal[i][2])*cf;
  const lum=0.85+Math.abs(reaction)*0.15;
  const edgeBright=1.0+edge*0.25;
  const glow=Math.max(0,reaction-0.5)*0.8;
  const glowR=r+glow*40,glowG=g+glow*30,glowB=b+glow*15;
  const vignette=1.0-Math.pow(dist/300,2)*0.3;
  return[
    Math.min(255,glowR*lum*edgeBright*vignette)|0,
    Math.min(255,glowG*lum*edgeBright*vignette)|0,
    Math.min(255,glowB*lum*edgeBright*vignette)|0
  ];
}
